      // Ant tuple: 0 id, 1 colony, 2 type, 3 x, 4 y, 5 dir, 6 carrying, 7 hp%, 8 hit flash (combat.js), 9 order flag (orders.js),
      // 10 current target's ant id (0 = none; ant17, drawn as target lines), 11 fire/move state code (orders.js stateCode)
      ants: this.ants.map(a => [a.id, a.colony, TYPE_IDS[a.type], r2(a.x), r2(a.y), r2(a.dir), a.carrying > 0 ? 1 : 0, Math.ceil(a.hp / STATS[a.type].hp * 100), this.hitFlash(a), ORDERS.orderFlag(a), a.foe || 0, ORDERS.stateCode(a)]),
      food: this.food.map(f => [f.id, r2(f.x), r2(f.y), f.amount]),
